def search_rotated(a, queries):
    """Trusted distinct rotated-sorted input; return indexes in original order."""
    out = []
    for target in queries:
        (lo, hi) = (0, len(a) - 1)
        found = -1
        while lo <= hi:
            mid = lo + (hi - lo) // 2
            if a[mid] == target:
                found = mid
                break
            if a[lo] <= a[mid]:
                if a[lo] <= target < a[mid]:
                    hi = mid - 1
                else:
                    lo = mid + 1
            elif a[mid] < target <= a[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
        out.append(str(found))
    return out

print(search_rotated([4, 5, 6, 7, 0, 1, 2], [0, 3, 4, 2]))
print(search_rotated([-2], [-2, 0]))

