def first_at_least(prices, queries):
    lines = []
    for target in queries:
        (lo, hi) = (0, len(prices))
        while lo < hi:
            mid = (lo + hi) // 2
            if prices[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        lines.append(str(lo if lo < len(prices) else -1))
    return lines

print(*first_at_least([2, 4, 4, 7], [4, 5, 8, 1]), sep='\n')

